def check_langford(seq, n):
    if len(seq) != 2 * n:
        return False

    positions = {}
    for i, val in enumerate(seq):
        if val not in positions:
            positions[val] = []
        positions[val].append(i)

    for v in range(1, n + 1):
        if v not in positions or len(positions[v]) != 2:
            return False
        if positions[v][1] - positions[v][0] != v + 1:
            return False
    return True

seq = [12, 10, 11, 6, 4, 5, 9, 7, 8, 4, 6, 5, 10, 12, 11, 7, 9, 8, 3, 1, 2, 1, 3, 2]
print(check_langford(seq, 12))
